-- Flashcard top-up: Biology|AQA|alevel — brings each topic up to 30 cards.
-- Generated by scripts/build-flashcard-topup.js from flashcards/topup/src/biology-aqa-alevel.txt
-- Safe to re-run: skips fronts already present and never takes a topic past 30.
WITH v(subject, exam_board, level, topic_id, topic_name, front, back, ord) AS (VALUES
  ('Biology', 'AQA', 'alevel', 'T1', 'Biological Molecules', 'What is a monomer and a polymer?', 'A monomer is a small unit that can join with others; a polymer is a large molecule made of many monomers joined together.', 1),
  ('Biology', 'AQA', 'alevel', 'T1', 'Biological Molecules', 'What is a glycosidic bond and how is it formed?', 'A covalent bond between two monosaccharides, formed by a condensation reaction that releases a molecule of water.', 2),
  ('Biology', 'AQA', 'alevel', 'T1', 'Biological Molecules', 'Which monosaccharides form maltose, sucrose and lactose?', 'Maltose: glucose + glucose. Sucrose: glucose + fructose. Lactose: glucose + galactose.', 3),
  ('Biology', 'AQA', 'alevel', 'T1', 'Biological Molecules', 'How does glycogen''s structure suit its function?', 'It is highly branched, so it can be hydrolysed rapidly at many ends to release glucose. It is insoluble and compact, so it is a good store in animals.', 4),
  ('Biology', 'AQA', 'alevel', 'T1', 'Biological Molecules', 'How does cellulose''s structure give plant cell walls strength?', 'β-glucose chains are straight and linked by many hydrogen bonds into microfibrils, which provide high tensile strength.', 5),
  ('Biology', 'AQA', 'alevel', 'T1', 'Biological Molecules', 'How is a test for non-reducing sugars carried out?', 'After a negative Benedict''s test, boil with dilute HCl, neutralise with sodium hydrogencarbonate, then repeat Benedict''s. A brick-red precipitate shows a non-reducing sugar.', 6),
  ('Biology', 'AQA', 'alevel', 'T1', 'Biological Molecules', 'What is a peptide bond and how is it formed?', 'A bond between the amine group of one amino acid and the carboxyl group of another, formed by condensation.', 7),
  ('Biology', 'AQA', 'alevel', 'T1', 'Biological Molecules', 'Give the general structure of an amino acid.', 'A central carbon bonded to an amine group (–NH2), a carboxyl group (–COOH), a hydrogen atom and a variable R group.', 8),
  ('Biology', 'AQA', 'alevel', 'T1', 'Biological Molecules', 'Why does temperature above the optimum reduce enzyme activity?', 'Hydrogen and ionic bonds in the tertiary structure break, changing the active site shape so substrates no longer fit (denaturation).', 9),
  ('Biology', 'AQA', 'alevel', 'T1', 'Biological Molecules', 'How does pH affect enzyme activity?', 'Changes in H+ concentration alter the charges on amino acids in the active site and break ionic and hydrogen bonds, changing its shape.', 10),
  ('Biology', 'AQA', 'alevel', 'T1', 'Biological Molecules', 'How does substrate concentration affect the rate of an enzyme-controlled reaction?', 'Rate increases as more enzyme–substrate complexes form, until all active sites are occupied; then enzyme concentration becomes limiting.', 11),
  ('Biology', 'AQA', 'alevel', 'T1', 'Biological Molecules', 'What is the role of DNA helicase and DNA polymerase in replication?', 'Helicase breaks hydrogen bonds between bases to unwind the strands. DNA polymerase joins free nucleotides by condensation, forming phosphodiester bonds.', 12),
  ('Biology', 'AQA', 'alevel', 'T1', 'Biological Molecules', 'How did Meselson and Stahl show DNA replication is semi-conservative?', 'Bacteria grown in 15N were transferred to 14N. After one generation, DNA was all intermediate density; after two, half intermediate and half light.', 13),
  ('Biology', 'AQA', 'alevel', 'T1', 'Biological Molecules', 'Why is ATP a suitable immediate energy source?', 'It releases energy in small, manageable amounts; hydrolysis is a single step; it is easily resynthesised; and it can phosphorylate other molecules.', 14),
  ('Biology', 'AQA', 'alevel', 'T1', 'Biological Molecules', 'What are the properties of water that matter to living organisms?', 'High specific heat capacity (buffers temperature), high latent heat of vaporisation (cooling), a good solvent, cohesion (water columns in xylem) and a metabolite.', 15),
  ('Biology', 'AQA', 'alevel', 'T2', 'Cells', 'What is the function of the mitochondria?', 'The site of aerobic respiration (link reaction, Krebs cycle and oxidative phosphorylation), producing ATP.', 1),
  ('Biology', 'AQA', 'alevel', 'T2', 'Cells', 'What is the function of the Golgi apparatus?', 'It modifies proteins (e.g. adding carbohydrates), packages them into vesicles, and forms lysosomes.', 2),
  ('Biology', 'AQA', 'alevel', 'T2', 'Cells', 'What are plasmids and why are they important in bacteria?', 'Small circular DNA loops separate from the main chromosome. They often carry genes such as antibiotic resistance and can be transferred between bacteria.', 3),
  ('Biology', 'AQA', 'alevel', 'T2', 'Cells', 'How do viruses differ from living cells?', 'They are acellular and non-living: genetic material (DNA or RNA) in a capsid, sometimes with an envelope and attachment proteins. They can only replicate inside host cells.', 4),
  ('Biology', 'AQA', 'alevel', 'T2', 'Cells', 'How do prokaryotic cells divide?', 'By binary fission: the circular DNA and plasmids replicate, the cell grows, and the cytoplasm divides into two daughter cells.', 5),
  ('Biology', 'AQA', 'alevel', 'T2', 'Cells', 'What is the role of cholesterol in cell membranes?', 'It binds to phospholipid tails, reducing fluidity and making the membrane more stable.', 6),
  ('Biology', 'AQA', 'alevel', 'T2', 'Cells', 'What is the role of glycoproteins and glycolipids in membranes?', 'Cell recognition and signalling (as receptors or antigens), and helping cells attach to each other.', 7),
  ('Biology', 'AQA', 'alevel', 'T2', 'Cells', 'How does temperature affect membrane permeability?', 'Above about 40 °C, phospholipids gain kinetic energy and proteins denature, making the membrane more permeable.', 8),
  ('Biology', 'AQA', 'alevel', 'T2', 'Cells', 'What is osmosis?', 'The net movement of water from a region of higher water potential to a region of lower water potential across a partially permeable membrane.', 9),
  ('Biology', 'AQA', 'alevel', 'T2', 'Cells', 'What are the factors affecting the rate of diffusion?', 'Surface area, concentration gradient, thickness of the exchange surface, and temperature.', 10),
  ('Biology', 'AQA', 'alevel', 'T2', 'Cells', 'What is an antigen?', 'A molecule (usually a protein) on the surface of a cell or virus that triggers an immune response.', 11),
  ('Biology', 'AQA', 'alevel', 'T2', 'Cells', 'What is a monoclonal antibody and give one use?', 'Identical antibodies from a single clone of B cells, binding to one specific antigen. Used in pregnancy tests, targeting cancer drugs, and ELISA.', 12),
  ('Biology', 'AQA', 'alevel', 'T2', 'Cells', 'What happens in phagocytosis?', 'A phagocyte engulfs a pathogen into a phagosome; a lysosome fuses with it and lysozymes hydrolyse the pathogen; antigens may be presented on the phagocyte''s surface.', 13),
  ('Biology', 'AQA', 'alevel', 'T3', 'Organisms Exchange Substances', 'How is surface area to volume ratio calculated and why does it matter?', 'Surface area ÷ volume. As organisms get larger the ratio decreases, so diffusion across the body surface is too slow to meet their needs.', 1),
  ('Biology', 'AQA', 'alevel', 'T3', 'Organisms Exchange Substances', 'Describe the pathway of air into the lungs.', 'Trachea → bronchi → bronchioles → alveoli.', 2),
  ('Biology', 'AQA', 'alevel', 'T3', 'Organisms Exchange Substances', 'Describe the mechanism of inspiration.', 'External intercostal muscles contract and the diaphragm contracts and flattens. Thorax volume increases, pressure falls below atmospheric, and air moves in.', 3),
  ('Biology', 'AQA', 'alevel', 'T3', 'Organisms Exchange Substances', 'Define tidal volume and ventilation rate.', 'Tidal volume: the volume of air breathed in or out in one normal breath. Ventilation rate: breaths per minute. Pulmonary ventilation = tidal volume × ventilation rate.', 4),
  ('Biology', 'AQA', 'alevel', 'T3', 'Organisms Exchange Substances', 'How does emphysema affect gas exchange?', 'Alveolar walls break down, reducing surface area, and elastin is lost, reducing recoil. Less oxygen diffuses into the blood.', 5),
  ('Biology', 'AQA', 'alevel', 'T3', 'Organisms Exchange Substances', 'What is the role of bile in lipid digestion?', 'Bile salts emulsify lipids into small droplets, increasing surface area for lipase.', 6),
  ('Biology', 'AQA', 'alevel', 'T3', 'Organisms Exchange Substances', 'How are monoglycerides and fatty acids absorbed?', 'Micelles carry them to the epithelial cells, where they diffuse in and are reformed into triglycerides, packaged into chylomicrons and enter the lacteals.', 7),
  ('Biology', 'AQA', 'alevel', 'T3', 'Organisms Exchange Substances', 'What is the Bohr effect?', 'Higher CO2 concentration lowers blood pH, reducing haemoglobin''s affinity for oxygen. The dissociation curve shifts right, so more oxygen is unloaded to respiring tissues.', 8),
  ('Biology', 'AQA', 'alevel', 'T3', 'Organisms Exchange Substances', 'Why do small mammals have haemoglobin with a lower affinity for oxygen?', 'They have a high metabolic rate, so their haemoglobin needs to unload oxygen readily to respiring tissues.', 9),
  ('Biology', 'AQA', 'alevel', 'T3', 'Organisms Exchange Substances', 'How is cardiac output calculated?', 'Cardiac output = stroke volume × heart rate.', 10),
  ('Biology', 'AQA', 'alevel', 'T3', 'Organisms Exchange Substances', 'What is the function of the coronary arteries?', 'To supply the heart muscle with oxygenated blood.', 11),
  ('Biology', 'AQA', 'alevel', 'T3', 'Organisms Exchange Substances', 'Why do veins have valves?', 'Blood is at low pressure, so valves prevent backflow and keep blood returning to the heart.', 12),
  ('Biology', 'AQA', 'alevel', 'T3', 'Organisms Exchange Substances', 'What are the roles of the atrioventricular and semilunar valves?', 'AV valves prevent backflow from ventricles to atria. Semilunar valves prevent backflow from the arteries into the ventricles.', 13),
  ('Biology', 'AQA', 'alevel', 'T3', 'Organisms Exchange Substances', 'What is root pressure?', 'Active transport of mineral ions into the xylem lowers the water potential, so water enters by osmosis and pushes water up the xylem.', 14),
  ('Biology', 'AQA', 'alevel', 'T3', 'Organisms Exchange Substances', 'What evidence supports the mass-flow hypothesis?', 'Sap is released when phloem is cut; the concentration of sucrose is higher in leaves than roots; ringing a stem causes swelling above the ring; aphid stylets show pressure.', 15),
  ('Biology', 'AQA', 'alevel', 'T4', 'Genetic Information & Variation', 'What is a codon and an anticodon?', 'Codon: a sequence of three mRNA bases coding for an amino acid. Anticodon: the complementary three bases on a tRNA molecule.', 1),
  ('Biology', 'AQA', 'alevel', 'T4', 'Genetic Information & Variation', 'What does it mean that the genetic code is degenerate?', 'More than one codon codes for the same amino acid.', 2),
  ('Biology', 'AQA', 'alevel', 'T4', 'Genetic Information & Variation', 'What are introns and exons?', 'Exons are the coding sequences of a gene; introns are non-coding sequences that are removed from pre-mRNA by splicing.', 3),
  ('Biology', 'AQA', 'alevel', 'T4', 'Genetic Information & Variation', 'Describe the structure of tRNA.', 'A single-stranded, cloverleaf-shaped RNA with an anticodon at one end and an amino acid binding site at the other, held by hydrogen bonds.', 4),
  ('Biology', 'AQA', 'alevel', 'T4', 'Genetic Information & Variation', 'What is the role of RNA polymerase in transcription?', 'It joins free RNA nucleotides complementary to the template DNA strand, forming phosphodiester bonds to make pre-mRNA.', 5),
  ('Biology', 'AQA', 'alevel', 'T4', 'Genetic Information & Variation', 'What is a mutagenic agent? Give two examples.', 'A factor that increases the rate of gene mutation, e.g. ionising radiation (X-rays, UV) and chemicals such as benzene.', 6),
  ('Biology', 'AQA', 'alevel', 'T4', 'Genetic Information & Variation', 'What is a frameshift mutation?', 'An addition or deletion of a base (not a multiple of three) that shifts the reading frame, changing every codon after it.', 7),
  ('Biology', 'AQA', 'alevel', 'T4', 'Genetic Information & Variation', 'What is non-disjunction?', 'The failure of chromosomes or chromatids to separate in meiosis, giving gametes with an extra or missing chromosome (e.g. Down''s syndrome).', 8),
  ('Biology', 'AQA', 'alevel', 'T4', 'Genetic Information & Variation', 'How does crossing over produce variation?', 'Homologous chromosomes pair up and exchange sections of chromatids at chiasmata, producing new combinations of alleles.', 9),
  ('Biology', 'AQA', 'alevel', 'T4', 'Genetic Information & Variation', 'How does independent segregation produce variation?', 'Homologous pairs line up randomly at the equator in meiosis I, so different combinations of maternal and paternal chromosomes go into each gamete.', 10),
  ('Biology', 'AQA', 'alevel', 'T4', 'Genetic Information & Variation', 'How many different gamete combinations can independent segregation produce?', '2^n, where n is the number of homologous pairs (2^23 in humans).', 11),
  ('Biology', 'AQA', 'alevel', 'T4', 'Genetic Information & Variation', 'What is a genetic bottleneck?', 'A sharp fall in population size that reduces genetic diversity, e.g. northern elephant seals.', 12),
  ('Biology', 'AQA', 'alevel', 'T4', 'Genetic Information & Variation', 'What is the founder effect?', 'A few individuals establish a new population, carrying only a small part of the original gene pool, which reduces genetic diversity.', 13),
  ('Biology', 'AQA', 'alevel', 'T4', 'Genetic Information & Variation', 'How does courtship behaviour help classification?', 'Courtship is species-specific, so it allows members of the same species to recognise each other and mate.', 14),
  ('Biology', 'AQA', 'alevel', 'T4', 'Genetic Information & Variation', 'What is phylogenetic classification?', 'Grouping organisms by their evolutionary relationships and common ancestry.', 15),
  ('Biology', 'AQA', 'alevel', 'T5', 'Energy Transfers', 'What is the role of chlorophyll in photosynthesis?', 'It absorbs light energy, which excites electrons in photosystems, starting the light-dependent reaction.', 1),
  ('Biology', 'AQA', 'alevel', 'T5', 'Energy Transfers', 'What is photolysis?', 'The splitting of water by light: 2H2O → 4H+ + 4e− + O2. It replaces electrons lost from chlorophyll.', 2),
  ('Biology', 'AQA', 'alevel', 'T5', 'Energy Transfers', 'What are the products of the light-dependent reaction used for?', 'ATP and reduced NADP are used in the light-independent reaction (Calvin cycle) to reduce GP to triose phosphate.', 3),
  ('Biology', 'AQA', 'alevel', 'T5', 'Energy Transfers', 'What is the role of RuBisCO?', 'It catalyses the fixation of CO2 with ribulose bisphosphate (RuBP) to form two molecules of glycerate-3-phosphate (GP).', 4),
  ('Biology', 'AQA', 'alevel', 'T5', 'Energy Transfers', 'Why does the concentration of RuBP rise and GP fall when CO2 is limited?', 'Less RuBP is used to fix CO2, while RuBP is still regenerated from triose phosphate, and less GP is formed.', 5),
  ('Biology', 'AQA', 'alevel', 'T5', 'Energy Transfers', 'Where do the light-dependent and light-independent reactions take place?', 'The light-dependent reaction takes place in the thylakoid membranes; the light-independent reaction takes place in the stroma.', 6),
  ('Biology', 'AQA', 'alevel', 'T5', 'Energy Transfers', 'What is the net ATP yield from glycolysis per glucose?', '2 ATP (4 made minus 2 used), plus 2 reduced NAD and 2 pyruvate.', 7),
  ('Biology', 'AQA', 'alevel', 'T5', 'Energy Transfers', 'What happens in the link reaction?', 'Pyruvate is decarboxylated and oxidised to acetate, which combines with coenzyme A to form acetyl coenzyme A; reduced NAD and CO2 are produced.', 8),
  ('Biology', 'AQA', 'alevel', 'T5', 'Energy Transfers', 'What is the role of oxygen in respiration?', 'It is the final electron acceptor at the end of the electron transport chain, combining with electrons and protons to form water.', 9),
  ('Biology', 'AQA', 'alevel', 'T5', 'Energy Transfers', 'Why is anaerobic respiration less efficient?', 'Only glycolysis produces ATP (2 per glucose); the link reaction, Krebs cycle and oxidative phosphorylation can''t occur without oxygen.', 10),
  ('Biology', 'AQA', 'alevel', 'T5', 'Energy Transfers', 'What is the role of NAD and FAD?', 'Coenzymes that accept hydrogen (become reduced) in glycolysis, the link reaction and Krebs cycle, carrying it to the electron transport chain.', 11),
  ('Biology', 'AQA', 'alevel', 'T5', 'Energy Transfers', 'What is primary productivity measured in?', 'Energy per unit area per unit time, e.g. kJ m^-2 yr^-1.', 12),
  ('Biology', 'AQA', 'alevel', 'T5', 'Energy Transfers', 'How can farming practices increase efficiency of energy transfer?', 'Reducing respiratory losses (restricting movement, keeping animals warm), and removing competitors and pests.', 13),
  ('Biology', 'AQA', 'alevel', 'T5', 'Energy Transfers', 'What is the role of mycorrhizae?', 'Fungi associated with plant roots that increase the surface area for water and mineral uptake; in return, they receive carbohydrates.', 14),
  ('Biology', 'AQA', 'alevel', 'T5', 'Energy Transfers', 'What is nitrogen fixation?', 'The conversion of atmospheric nitrogen gas into ammonium compounds by bacteria such as Rhizobium in root nodules.', 15),
  ('Biology', 'AQA', 'alevel', 'T6', 'Organisms Respond to Changes', 'What is a kinesis?', 'A non-directional response in which the rate of movement changes with the intensity of a stimulus, e.g. woodlice moving faster in dry conditions.', 1),
  ('Biology', 'AQA', 'alevel', 'T6', 'Organisms Respond to Changes', 'What is a taxis?', 'A directional movement towards (positive) or away from (negative) a stimulus.', 2),
  ('Biology', 'AQA', 'alevel', 'T6', 'Organisms Respond to Changes', 'How does IAA cause phototropism in shoots?', 'IAA moves to the shaded side, stimulating cell elongation there, so the shoot bends towards the light.', 3),
  ('Biology', 'AQA', 'alevel', 'T6', 'Organisms Respond to Changes', 'Why does IAA cause roots to grow downwards?', 'IAA builds up on the lower side of roots and inhibits cell elongation there, so the upper side grows more and the root bends downwards.', 4),
  ('Biology', 'AQA', 'alevel', 'T6', 'Organisms Respond to Changes', 'Why do cones give higher visual acuity than rods?', 'Each cone connects to its own bipolar neurone, so the brain receives separate impulses from each.', 5),
  ('Biology', 'AQA', 'alevel', 'T6', 'Organisms Respond to Changes', 'What are the roles of the sympathetic and parasympathetic nervous systems in controlling heart rate?', 'Sympathetic increases the frequency of impulses from the SAN, speeding up heart rate. Parasympathetic decreases it, slowing heart rate.', 6),
  ('Biology', 'AQA', 'alevel', 'T6', 'Organisms Respond to Changes', 'What is the refractory period and why is it important?', 'After an action potential, the axon membrane can''t be stimulated again. This makes impulses discrete, unidirectional, and limits their frequency.', 7),
  ('Biology', 'AQA', 'alevel', 'T6', 'Organisms Respond to Changes', 'What factors affect speed of conduction of an impulse?', 'Myelination (saltatory conduction), axon diameter (wider is faster), and temperature.', 8),
  ('Biology', 'AQA', 'alevel', 'T6', 'Organisms Respond to Changes', 'What is a neuromuscular junction?', 'A synapse between a motor neurone and a muscle fibre, using acetylcholine to trigger muscle contraction.', 9),
  ('Biology', 'AQA', 'alevel', 'T6', 'Organisms Respond to Changes', 'What is the role of calcium ions in muscle contraction?', 'Ca2+ binds to troponin, moving tropomyosin to expose myosin binding sites on actin, so cross-bridges can form.', 10),
  ('Biology', 'AQA', 'alevel', 'T6', 'Organisms Respond to Changes', 'What is the role of ATP in muscle contraction?', 'ATP hydrolysis provides energy for the power stroke and allows myosin heads to detach from actin.', 11),
  ('Biology', 'AQA', 'alevel', 'T7', 'Genetics, Populations & Evolution', 'What is codominance?', 'Both alleles are expressed in the phenotype of a heterozygote, e.g. the AB blood group.', 1),
  ('Biology', 'AQA', 'alevel', 'T7', 'Genetics, Populations & Evolution', 'What are multiple alleles?', 'A gene with more than two alleles, e.g. IA, IB and IO for ABO blood groups.', 2),
  ('Biology', 'AQA', 'alevel', 'T7', 'Genetics, Populations & Evolution', 'Why does a dihybrid cross with linked genes not give a 9:3:3:1 ratio?', 'Linked genes are on the same chromosome and usually inherited together, so fewer recombinant phenotypes appear (unless crossing over occurs).', 3),
  ('Biology', 'AQA', 'alevel', 'T7', 'Genetics, Populations & Evolution', 'In the Hardy–Weinberg equations, what do p and q represent?', 'p is the frequency of the dominant allele and q the frequency of the recessive allele; p + q = 1.', 4),
  ('Biology', 'AQA', 'alevel', 'T7', 'Genetics, Populations & Evolution', 'What conditions are required for Hardy–Weinberg equilibrium?', 'A large population, random mating, no mutation, no migration and no selection.', 5),
  ('Biology', 'AQA', 'alevel', 'T7', 'Genetics, Populations & Evolution', 'What is genetic drift?', 'A random change in allele frequency, most significant in small populations.', 6),
  ('Biology', 'AQA', 'alevel', 'T7', 'Genetics, Populations & Evolution', 'What is a gene pool?', 'All the alleles of all the genes in a population at a given time.', 7),
  ('Biology', 'AQA', 'alevel', 'T7', 'Genetics, Populations & Evolution', 'What is a population?', 'All the organisms of one species living in the same area at the same time that can interbreed.', 8),
  ('Biology', 'AQA', 'alevel', 'T7', 'Genetics, Populations & Evolution', 'What is a community?', 'All the populations of different species living in the same area at the same time.', 9),
  ('Biology', 'AQA', 'alevel', 'T7', 'Genetics, Populations & Evolution', 'What is a niche?', 'The role of a species within its habitat, including its biotic and abiotic interactions.', 10),
  ('Biology', 'AQA', 'alevel', 'T7', 'Genetics, Populations & Evolution', 'What is interspecific competition?', 'Competition between different species for the same resources, which can reduce population sizes or exclude one species.', 11),
  ('Biology', 'AQA', 'alevel', 'T7', 'Genetics, Populations & Evolution', 'What is a pioneer species?', 'The first species to colonise bare ground in succession, e.g. lichens, which can survive in harsh abiotic conditions.', 12),
  ('Biology', 'AQA', 'alevel', 'T7', 'Genetics, Populations & Evolution', 'What is a climax community?', 'The final stable community in succession, with high biodiversity.', 13),
  ('Biology', 'AQA', 'alevel', 'T7', 'Genetics, Populations & Evolution', 'What conditions are needed for mark–release–recapture to be valid?', 'Marks don''t affect survival, marked individuals mix fully, and there is no significant migration, birth or death between samples.', 14),
  ('Biology', 'AQA', 'alevel', 'T7', 'Genetics, Populations & Evolution', 'Why might chi-squared show a significant difference from an expected ratio?', 'Linkage, epistasis, sex linkage, lethal alleles, or a small sample size.', 15),
  ('Biology', 'AQA', 'alevel', 'T8', 'Control of Gene Expression', 'What is a transcription factor?', 'A protein that binds to a specific DNA promoter region to stimulate or inhibit transcription of a gene.', 1),
  ('Biology', 'AQA', 'alevel', 'T8', 'Control of Gene Expression', 'What is epigenetics?', 'Heritable changes in gene function without changes to the base sequence of DNA, e.g. methylation and histone acetylation.', 2),
  ('Biology', 'AQA', 'alevel', 'T8', 'Control of Gene Expression', 'How does increased methylation affect transcription?', 'Methyl groups on the DNA (usually at CpG sites) prevent transcription factors from binding, silencing the gene.', 3),
  ('Biology', 'AQA', 'alevel', 'T8', 'Control of Gene Expression', 'How does acetylation of histones affect transcription?', 'Acetylation loosens chromatin, allowing transcription factors to bind and increasing transcription.', 4),
  ('Biology', 'AQA', 'alevel', 'T8', 'Control of Gene Expression', 'What is a benign tumour and a malignant tumour?', 'Benign: slow-growing, doesn''t spread, usually encapsulated. Malignant: grows rapidly, invades tissues and spreads (metastasis).', 5),
  ('Biology', 'AQA', 'alevel', 'T8', 'Control of Gene Expression', 'How does oestrogen increase the risk of breast cancer?', 'It can activate transcription of genes that promote cell division, e.g. in cells with mutated genes, leading to tumour growth.', 6),
  ('Biology', 'AQA', 'alevel', 'T8', 'Control of Gene Expression', 'What is the Human Genome Project and one benefit of it?', 'The mapping of the complete human DNA sequence. It helps identify disease-causing mutations and develop personalised medicine.', 7),
  ('Biology', 'AQA', 'alevel', 'T8', 'Control of Gene Expression', 'Why is it difficult to translate the genome of complex organisms into a proteome?', 'They have non-coding DNA and regulatory genes, and alternative splicing produces many proteins from one gene.', 8),
  ('Biology', 'AQA', 'alevel', 'T8', 'Control of Gene Expression', 'What are sticky ends?', 'Short single-stranded overhangs produced by restriction enzymes cutting at palindromic sequences, allowing complementary DNA fragments to join.', 9),
  ('Biology', 'AQA', 'alevel', 'T8', 'Control of Gene Expression', 'How is reverse transcriptase used to make a gene?', 'It makes complementary DNA (cDNA) from mRNA, so the gene has no introns and can be expressed in bacteria.', 10),
  ('Biology', 'AQA', 'alevel', 'T8', 'Control of Gene Expression', 'What is the role of DNA ligase?', 'It joins the sugar–phosphate backbones of DNA fragments by forming phosphodiester bonds.', 11),
  ('Biology', 'AQA', 'alevel', 'T8', 'Control of Gene Expression', 'Give two uses of recombinant DNA technology.', 'Production of human insulin in bacteria, and GM crops (e.g. Golden Rice with added vitamin A).', 12),
  ('Biology', 'AQA', 'alevel', 'T8', 'Control of Gene Expression', 'What are VNTRs and why are they useful in DNA profiling?', 'Variable number tandem repeats: non-coding repeated sequences that vary between individuals, so they give a unique profile.', 13),
  ('Biology', 'AQA', 'alevel', 'T8', 'Control of Gene Expression', 'How is genetic screening used?', 'Labelled DNA probes identify specific alleles, e.g. BRCA1 mutations or cystic fibrosis, to inform decisions and treatment.', 14)
),
fresh AS (
  SELECT v.* FROM v
  WHERE NOT EXISTS (
    SELECT 1 FROM flashcards f
    WHERE f.subject = v.subject AND f.exam_board = v.exam_board AND f.level = v.level
      AND f.topic_id = v.topic_id AND f.front = v.front)
),
cur AS (
  SELECT subject, exam_board, level, topic_id, count(*) AS n, max(card_order) AS mx
  FROM flashcards
  WHERE subject = 'Biology' AND exam_board = 'AQA' AND level = 'alevel'
  GROUP BY 1, 2, 3, 4
),
ranked AS (
  SELECT fr.*, coalesce(c.n, 0) AS n, coalesce(c.mx, 0) AS mx,
         row_number() OVER (PARTITION BY fr.topic_id ORDER BY fr.ord) AS rn
  FROM fresh fr
  LEFT JOIN cur c USING (subject, exam_board, level, topic_id)
)
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level)
SELECT subject, exam_board, topic_id, topic_name, front, back, mx + rn, level
FROM ranked
WHERE n + rn <= 30;
